package pl.zagranietyper.service;
import org.junit.jupiter.api.Test;import pl.zagranietyper.model.*;import java.math.BigDecimal;import java.time.Instant;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class FootballPeriodStatisticSettlementEngineTest {private final FootballPeriodStatisticSettlementEngine e=new FootballPeriodStatisticSettlementEngine();@Test void settlesFirstSecondAndEachHalfThroughGenericArithmetic(){assertEquals(SettlementDecision.W,e.settle(c(false,FootballPeriodStatisticsSnapshot.Period.FIRST_HALF),s(v(FootballPeriodStatisticsSnapshot.Period.FIRST_HALF,3))));assertEquals(SettlementDecision.W,e.settle(c(false,FootballPeriodStatisticsSnapshot.Period.SECOND_HALF),s(v(FootballPeriodStatisticsSnapshot.Period.SECOND_HALF,3))));assertEquals(SettlementDecision.L,e.settle(c(true,FootballPeriodStatisticsSnapshot.Period.FIRST_HALF),s(v(FootballPeriodStatisticsSnapshot.Period.FIRST_HALF,1),v(FootballPeriodStatisticsSnapshot.Period.SECOND_HALF,3))));}@Test void missingPeriodIsUnsupported(){assertEquals(SettlementDecision.UNSUPPORTED,e.settle(c(true,FootballPeriodStatisticsSnapshot.Period.FIRST_HALF),s(v(FootballPeriodStatisticsSnapshot.Period.FIRST_HALF,3))));}private static FootballPeriodStatisticCondition c(boolean each,FootballPeriodStatisticsSnapshot.Period p){return new FootballPeriodStatisticCondition(p,FootballFixtureStatisticCondition.threshold(FootballFixtureStatisticType.CORNERS,FootballFixtureStatisticCondition.Subject.AWAY,FootballFixtureStatisticCondition.Comparison.OVER,new BigDecimal("1.5")),each);}private static FootballPeriodStatisticsSnapshot.Value v(FootballPeriodStatisticsSnapshot.Period p,int n){return new FootballPeriodStatisticsSnapshot.Value(p,FootballFixtureStatisticType.CORNERS,FootballFixtureStatisticsSnapshot.TeamSide.AWAY,BigDecimal.valueOf(n),FootballFixtureStatisticsSnapshot.ValueStatus.KNOWN,"Corners");}private static FootballPeriodStatisticsSnapshot s(FootballPeriodStatisticsSnapshot.Value...v){return new FootballPeriodStatisticsSnapshot(1,"TEST","x",FootballPeriodStatisticsSnapshot.FetchStatus.COMPLETE,"{}",Instant.EPOCH,List.of(v));}}
